package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates each grade has on each sheet, each from its from-date on (or from the beginning of time)
 * through its to-date (or with no end).
 * Setting a grade's rate for a from-date it already has a rate for replaces that rate. */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateChain chain;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final ClaimRepository claims;
    private final PersonRepository people;

    public RateService(RateRepository rates, RateChain chain, SheetRepository sheets, Audit audit, RollupService rollup,
            ClaimRepository claims, PersonRepository people) {
        this.chain = chain;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The sheet's rates, by grade, then by from-date. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAndFrom(sheetId);
    }

    /** The sheet's rates, then its parent's, and so on up to {@link RateChain#LEVELS_UP} levels up: each
     * by grade, then by from-date. */
    @Transactional(readOnly = true)
    public List<List<Rate>> levels(String sheetId) {
        return chain.levels(sheetId);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
        if (from != null && to != null && to.isBefore(from)) {
            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = (from == null ? rates.findUndated(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from)).orElse(null);
        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, pct));
        } else {
            rate.setPct(pct);
            rate.setTo(to);
            rates.flush();
        }
        List<String> fields = new ArrayList<>(List.of("grade=" + grade,
                "rate=" + rate.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()));
        if (from != null) fields.add("from=" + from);
        if (to != null) fields.add("to=" + to);
        audit.change("RATE_SET", sheetId, user, fields.toArray(String[]::new));
        rollup.recordSince(sheetId, user, before);
        return rate;
    }

    /** How many OPEN and PENDING claims would show a different due, and by how much in all (new minus
     * current), were {@code pct} the grade's rate on every date. */
    public record Preview(int count, BigDecimal diff) {
    }

    /** A preview of the grade's rate at {@code pct} on every date over the OPEN and PENDING claims of the
     * people on the grade on each claim's date; a claim a statement binds does not change. Saves nothing. */
    @Transactional(readOnly = true)
    public Preview preview(String sheetId, String grade, BigDecimal pct) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        RollupService.Basis live = rollup.live(sheetId);
        RollupService.Basis previewed = RollupService.withRate(live, grade, pct);
        int count = 0;
        BigDecimal diff = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findBySheetIdOrderByListedDescIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) continue;
            BigDecimal now = rollup.shownOf(claim, person, live);
            BigDecimal then = rollup.shownOf(claim, person, previewed);
            if (Objects.equals(now, then) || (now != null && then != null && now.compareTo(then) == 0)) continue;
            count++;
            diff = diff.add(then == null ? BigDecimal.ZERO : then).subtract(now == null ? BigDecimal.ZERO : now);
        }
        return new Preview(count, diff.setScale(2, RoundingMode.HALF_EVEN));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.SheetHistory;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** The rates of a sheet's grades. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /** A grade's rate, the date it applies from (null: from the beginning of time) and the date it applies
     * through (null: with no end); the percent is
     * sent as text with two decimals so it is never rounded on the way; its level is 0 for the sheet's own
     * rate, 1 for its parent's, 2 for its parent's parent's, and so on (see {@link RateChain}). */
    public record RateView(String grade, String pct, LocalDate from, LocalDate to, int level) {
        static RateView of(Rate rate) {
            return of(rate, 0);
        }

        static RateView of(Rate rate, int level) {
            return new RateView(rate.getGrade(), rate.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    rate.getFrom(), rate.getTo(), level);
        }
    }

    /** A rate: a percent of 0.00 or more, with up to two decimals, and the date it applies from (null: from
     * the beginning of time) and through (null: with no end), which is not before its from-date. */
    public record RateRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String pct,
            LocalDate from, LocalDate to) {

        BigDecimal pctValue() {
            return new BigDecimal(pct.trim()).setScale(2);
        }
    }

    private final RateService service;

    private final SheetHistory history;

    public RateController(RateService service, SheetHistory history) {
        this.service = service;
        this.history = history;
    }

    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        List<List<Rate>> levels = asOf == null ? service.levels(sheetId.trim())
                : history.read(sheetId.trim(), asOf).rateLevels();
        List<RateView> views = new ArrayList<>();
        for (int level = 0; level < levels.size(); level++) {
            for (Rate rate : levels.get(level)) views.add(RateView.of(rate, level));
        }
        return views;
    }

    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RateRequest request) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, request.from(), request.to(), request.pctValue()));
    }

    /** A rate preview: how many claims would show a different due, and the sum of the differences as
     * text with two decimals. */
    public record PreviewView(int count, String diff) {
    }

    @GetMapping("/{grade}/preview")
    public PreviewView preview(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestParam @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String pct) {
        RateService.Preview preview = service.preview(sheetId.trim(), grade, new BigDecimal(pct.trim()).setScale(2));
        return new PreviewView(preview.count(), preview.diff().toPlainString());
    }
}
package net.officefloor.hq.app.rate;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** Setting a rate whose to-date is before its from-date. */
@ResponseStatus(HttpStatus.CONFLICT)
public class RateRefusedException extends RuntimeException {

    public RateRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.paste;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.claim.ClaimService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The claim paste box of a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/claims/paste")
@Validated
public class PasteController {

    /** The pasted lines of {@code name,amount,date,note}. */
    public record PasteRequest(@NotNull @Size(max = 200_000) String text) {
    }

    /** How many claims were added, and the claims, in the order of their lines. */
    public record PasteView(int added, List<ClaimView> claims) {
    }

    private final PasteService service;
    private final ClaimService claimService;

    public PasteController(PasteService service, ClaimService claimService) {
        this.service = service;
        this.claimService = claimService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PasteView paste(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PasteRequest request) {
        List<ClaimView> claims = ClaimView.allOf(service.paste(sheetId.trim(), user.trim(), request.text()), claimService);
        return new PasteView(claims.size(), claims);
    }
}
